        "Форми: strömt aus, strömte aus. Якщо щось витікає й відбувається рух, допоміжне дієслово в Perfekt — sein: Das Gas ist ausgeströmt. З додатком у знахідному відмінку (Ruhe ausströmen) вживають haben: Sie hat Ruhe ausgeströmt.",
        "Слово близьке до strömen (текти, литися). Найчастіше його вживають у технічному значенні, коли йдеться про витік газу, і в переносному — про враження, яке справляє людина."
