      "layout": "standardStudy",
      "translation": "об’єднуватися • об’єднатися",
      "explanation": [
        "Головна думка: sich vereinigen означає об’єднуватися, з’єднуватися разом — про держави, партії, підприємства, сили. Через mit + Dativ називають партнера: sich mit einer Gruppe vereinigen. Результат позначають через zu + Dativ: sich zu einer Union vereinigen.",
        "Форми: vereinigt sich, vereinigte sich, hat sich vereinigt. Без sich дієслово vereinigen перехідне: Länder vereinigen — об’єднувати країни. Приклад у назві: die Vereinigten Staaten."
      ],
